// Stand-in for cn@0.5.2: the bundled grammar, minus the Tailwind 3
// `bg-gradient-to` entry cn dropped from bg-image. An unmatched
// bg-gradient-to-* then falls through to bg-color.
const real = require("../../../../../node_modules/cn/dist/config.cjs")
exports.defaultConfig = () => {
  const config = real.defaultConfig()
  config.classGroups["bg-image"] = config.classGroups["bg-image"].filter(
    (entry) =>
      !(
        entry &&
        typeof entry === "object" &&
        !Array.isArray(entry) &&
        Object.hasOwn(entry, "bg-gradient-to")
      )
  )
  return config
}
exports.mergeConfigs = real.mergeConfigs
